// Normalizza i campi del form Meta e passa page_id/form_id per l'auto-routing
const j = $input.item.json;

function pick(obj, terms) {
  for (const k of Object.keys(obj)) {
    const kn = k.toLowerCase();
    if (terms.some((t) => kn.includes(t))) {
      const v = obj[k];
      if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
    }
  }
  return null;
}

// Se arrivano in formato grezzo Meta (field_data), li appiattisce
let flat = { ...j };
if (Array.isArray(j.field_data)) {
  for (const f of j.field_data) {
    const val = Array.isArray(f.values) ? f.values[0] : f.value;
    flat[f.name] = val;
  }
}

const full = pick(flat, ['full name', 'nome e cognome', 'nome_completo', 'nome', 'name']);
const first = pick(flat, ['first', 'nome']);
const last = pick(flat, ['last', 'cognome']);
const name = full || [first, last].filter(Boolean).join(' ') || null;
const phone = pick(flat, ['phone', 'telefono', 'cellulare', 'numero']);
const email = pick(flat, ['email', 'e-mail', 'mail']);

// ID Pagina / Modulo Meta: il CRM li usa per capire di quale cliente e' il lead
const page_id = pick(flat, ['page_id', 'pageid']) || j.page_id || null;
const form_id = pick(flat, ['form_id', 'formid']) || j.form_id || null;

return [{ json: { name, phone, email, page_id, form_id } }];
